import{_ as l,a8 as a,o as n,c as i,ah as s,K as t}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const P=JSON.parse('{"title":"工作汇报方法论（向老板汇报）","description":"","frontmatter":{"type":"preference","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["偏好","汇报","向上管理"]},"headers":[],"relativePath":"vault/Memory/Preferences/工作汇报方法论.md","filePath":"vault/Memory/Preferences/工作汇报方法论.md","lastUpdated":1789374053000}'),c={name:"vault/Memory/Preferences/工作汇报方法论.md"};function d(_,e,h,p,m,b){const r=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return n(),i("div",null,[e[0]||(e[0]=s('<h1 id="工作汇报方法论-向老板汇报" tabindex="-1">工作汇报方法论（向老板汇报） <a class="header-anchor" href="#工作汇报方法论-向老板汇报" aria-label="Permalink to “工作汇报方法论（向老板汇报）”">​</a></h1><p>来源：帮老适入职一月汇报（2026-08-14/15）定稿过程。完整出处：<code>E:\\Projects\\work\\帮老适\\2026年8月15日工作汇报\\</code>（含《如何写一份好的汇报_参考指南》）。</p><h2 id="结构与写法" tabindex="-1">结构与写法 <a class="header-anchor" href="#结构与写法" aria-label="Permalink to “结构与写法”">​</a></h2><ul><li>结论区分 <strong>activity 与 outcome</strong>（老板看价值，不是看做了什么）。</li><li>原因写取舍，不复述目的。</li><li>必须补「需老板决策/支持」段。</li><li>主线/支线结构：核心项目为主线，小工具/支线项目简略带过。</li><li>对比类文档保持中立，不替老板下结论；文档要精炼到「扫一眼」。</li></ul><h2 id="敏感红线-对内汇报也要守" tabindex="-1">敏感红线（对内汇报也要守） <a class="header-anchor" href="#敏感红线-对内汇报也要守" aria-label="Permalink to “敏感红线（对内汇报也要守）”">​</a></h2><p>删个人隐私（GitHub/姓名/本地工作目录）、AI 助手内部运维细节、具体个人账号与内部人名（如「某律师 suncounsel」→「ima 知识库（4万+内容共享法律库）」）；<strong>不写「公司无清晰 AI 目标」类负面判断</strong>；删个人能力证据类内容（属个人而非工作汇报）。</p><h2 id="数字口径" tabindex="-1">数字口径 <a class="header-anchor" href="#数字口径" aria-label="Permalink to “数字口径”">​</a></h2><p>「暂无依据不预估」——效果未实测前不写预估数字；财务类成果用可验证表述（「经财务部反馈该流程已可跑通、可常态化使用」）替代抽象的「大幅减少」。</p><h2 id="正式格式" tabindex="-1">正式格式 <a class="header-anchor" href="#正式格式" aria-label="Permalink to “正式格式”">​</a></h2><p>称谓「尊敬的总经理」+ 汇报周期 + 汇报人署名（帮老适时期：刘昊晴）。</p>',10)),t(r),t(o)])}const g=l(c,[["render",d]]);export{P as __pageData,g as default};
